'use client';

import { createField } from '@dawitlabs/pixelfield';
import { useEffect, useRef } from 'react';

export interface CurrentProps {
  className?: string;
  tint?: string;
  seed?: number;
  interactive?: boolean;
}

export function Current({ className, tint, seed = 0, interactive = true }: CurrentProps) {
  const ref = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const canvas = ref.current;
    if (!canvas) return;
    const field = createField(canvas, {
      generator: 'waves',
      falloff: 'fill',
      scale: 1.5,
      aspect: 1,
      warp: 1.1,
      contrast: 1.5,
      mode: 'billow',
      speed: 1.4,
      intensity: 1,
      flow: { x: 0, y: 0 },
      seed,
      tint,
      interactive,
    });
    return () => field.destroy();
  }, [tint, seed, interactive]);

  return <canvas ref={ref} className={className} aria-hidden="true" />;
}

import { createField } from '@dawitlabs/pixelfield';

export function mountCurrent(canvas, { tint, seed = 0, interactive = true } = {}) {
  return createField(canvas, {
      generator: 'waves',
      falloff: 'fill',
      scale: 1.5,
      aspect: 1,
      warp: 1.1,
      contrast: 1.5,
      mode: 'billow',
      speed: 1.4,
      intensity: 1,
      flow: { x: 0, y: 0 },
    seed,
    tint,
    interactive,
  });
}
